package com.bank.core;

import java.math.BigDecimal;

public class Account {
    private final String accountId;   // reference field (object on heap)
    private final String holderName;  // reference field
    private BigDecimal balance;        // reference field
    private int txnCount;              // PRIMITIVE INSTANCE FIELD → lives on heap inside this object

    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }

    public void debit(BigDecimal amount) {
        this.balance = this.balance.subtract(amount);
        this.txnCount++; // mutates the heap-resident primitive field
    }

    public void credit(BigDecimal amount) {
        this.balance = this.balance.add(amount);
        this.txnCount++;
    }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public int getTxnCount() { return txnCount; }
}
