package com.bank.core;

import java.math.BigDecimal;
import java.util.logging.*;

public class TransferService {
    private static final Logger log = Logger.getLogger("BankLog");

    // PRIMITIVE STATIC FIELD → one copy with the class in method area / Metaspace
    private static int totalTransfers = 0;

    public void transfer(Account from, Account to, BigDecimal rentAmount) {
        // rentAmount is a parameter; the int flag below is a PRIMITIVE LOCAL → stack frame
        int steps = 0; // local primitive, lives only during this method call
        from.debit(rentAmount);  steps++;
        to.credit(rentAmount);   steps++;
        totalTransfers++;        // updates the shared static (Metaspace)
        int done = steps;        // another local on the stack
        log.info(() -> "Transfer of Rs." + rentAmount + " done in " + done + " steps");
    }

    public static int getTotalTransfers() { return totalTransfers; }
}
