package com.bank.core;

import java.math.BigDecimal;
import java.util.logging.*;

public class MemoryRegionDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // References rajesh and priya are LOCALS on the stack;
        // the Account OBJECTS they point to live on the HEAP.
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00"));

        TransferService service = new TransferService();
        BigDecimal rentAmount = new BigDecimal("50000.00");

        service.transfer(rajesh, priya, rentAmount);
        service.transfer(rajesh, priya, new BigDecimal("12000.00"));

        log.info("Where each primitive lives:");
        log.info(() -> "STACK  : local 'steps'/'done' inside transfer() — already discarded");
        log.info(() -> "HEAP   : rajesh.txnCount = " + rajesh.getTxnCount()
                       + " (instance field inside the Account object)");
        log.info(() -> "HEAP   : priya.txnCount  = " + priya.getTxnCount());
        log.info(() -> "METASPACE: TransferService.totalTransfers = "
                       + TransferService.getTotalTransfers() + " (static, shared by all)");
    }
}
